func testAccCheckDataflowConfigStoreSettingDestroyProducer(t *testing.T) func(s *terraform.State) error {
	return func(s *terraform.State) error {
		for name, rs := range s.RootModule().Resources {
			if rs.Type != "google_dataflow_config_store_setting" {
				continue
			}
			if strings.HasPrefix(name, "data.") {
				continue
			}

			config := acctest.GoogleProviderConfig(t)
			origUserProjectOverride := config.UserProjectOverride
			config.UserProjectOverride = true
			defer func() {
				config.UserProjectOverride = origUserProjectOverride
			}()

			url, err := tpgresource.ReplaceVarsForTest(config, rs, "{{DataflowBasePath}}{{parent}}/locations/{{location}}/configStoreSettings/{{config_store_setting_id}}")
			if err != nil {
				return err
			}

			billingProject := ""
			if config.BillingProject != "" {
				billingProject = config.BillingProject
			} else if config.Project != "" {
				billingProject = config.Project
			}

			_, err = transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
				Config:    config,
				Method:    "GET",
				Project:   billingProject,
				RawURL:    url,
				UserAgent: config.UserAgent,
			})
			if err == nil {
				return fmt.Errorf("DataflowConfigStoreSetting still exists at %s", url)
			}
		}

		return nil
	}
}
